-- 在 Supabase SQL Editor 一次執行。執行後請在 Authentication > Users 建立第一位管理員。
create extension if not exists pgcrypto;
create type public.user_role as enum ('admin','super_admin');
create type public.order_status as enum ('pending','preparing','completed','cancelled');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text, role public.user_role not null default 'admin', created_at timestamptz not null default now());
create table public.menu_items (id uuid primary key default gen_random_uuid(), name text not null, description text, category text default '便當', price numeric(10,2) not null check(price>=0), image_url text, is_available boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), order_number text unique not null default upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)), pickup_date date not null, customer_name text not null, phone text not null, department text not null, note text, total_amount numeric(10,2) not null check(total_amount>=0), status public.order_status not null default 'pending', created_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, menu_item_id uuid references public.menu_items(id) on delete set null, name text not null, price numeric(10,2) not null, quantity integer not null check(quantity>0));
create or replace function public.is_admin() returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid()); $$;
create or replace function public.is_super_admin() returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='super_admin'); $$;
alter table public.profiles enable row level security; alter table public.menu_items enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
create policy "profiles self or admins read" on profiles for select using (id=auth.uid() or is_admin());
create policy "super admins manage profiles" on profiles for all using (is_super_admin()) with check (is_super_admin());
create policy "public read available menu" on menu_items for select using (is_available=true or is_admin());
create policy "admins manage menu" on menu_items for insert with check (is_admin()); create policy "admins update menu" on menu_items for update using (is_admin()) with check (is_admin()); create policy "admins delete menu" on menu_items for delete using (is_admin());
create policy "admins read orders" on orders for select using (is_admin()); create policy "admins update orders" on orders for update using (is_admin()) with check (is_admin()); create policy "admins read order items" on order_items for select using (is_admin());
create or replace function public.create_order(p_pickup_date date,p_customer_name text,p_phone text,p_department text,p_note text,p_total_amount numeric,p_items jsonb) returns text language plpgsql security definer set search_path=public as $$ declare v_order_id uuid; v_number text; v_taipei timestamp; begin v_taipei := now() at time zone 'Asia/Taipei'; if p_pickup_date=v_taipei::date and v_taipei::time >= time '11:30' then raise exception 'cutoff'; end if; if p_pickup_date < v_taipei::date then raise exception 'past_date'; end if; insert into orders(pickup_date,customer_name,phone,department,note,total_amount) values(p_pickup_date,p_customer_name,p_phone,p_department,p_note,p_total_amount) returning id,order_number into v_order_id,v_number; insert into order_items(order_id,menu_item_id,name,price,quantity) select v_order_id,(x->>'menu_item_id')::uuid,x->>'name',(x->>'price')::numeric,(x->>'quantity')::integer from jsonb_array_elements(p_items) x; return v_number; end; $$;
grant execute on function public.create_order(date,text,text,text,text,numeric,jsonb) to anon,authenticated;
insert into public.menu_items(name,description,category,price,sort_order) values ('香煎雞腿便當','香煎雞腿、時蔬與白飯','便當',110,1),('台式滷排骨便當','古早味滷排骨與每日配菜','便當',100,2);
